    tvRadioTitle: 'টিভি, মিউজিক ও রেডিও',
    tvRadioDesc: 'আপনার অ্যাপ খুলে ফেলার মুহুর্ত থেকেই দেখার বা শুনার জন্য কন্টিনিউয়াস এন্টারটেইনমেন্ট সারফেস দিচ্ছে ডিহাব। এই রিলাক্সড এক্সপেরিয়েন্সগুলো কন্টিনিউয়াস রান করে এবং ফ্লোটিং প্লেয়ার মাধ্যমে আপনার প্রোডাক্টের বিভিন্ন অংশে আপনাকে অনুসরণ করে, তাই যখনই আপনি অন্য জায়গায় নেভিগেট করবেন, মিডিয়া থামবে না।',
