    workDesc: 'বাউন্টি হান্টিং ডিহাবের ইনবিল্ট টাস্ক ও রিওয়ার্ড সিস্টেম, নন থার্ড পার্টি ফ্রিল্যান্স মার্কেটপ্লেস। ইকোসিস্টেমের কেউই বাউন্টি পোস্ট করতে পারে, আর কেউই হান্টার হয়ে তা নিতে পারে, রিওয়ার্ড সেফলি ডেলিভারি পর্যন্ত রেখে দেওয়া হয়। এটি কাজ ও ইঙ্গেজমেন্টকে প্ল্যাটফর্মের নেটিভ পার্টে রূপান্তর করে: বাউন্টি পোস্ট করা লোকজন, কাজ সম্পন্ন করা হান্টার ও তাদেরকে সেটল করার টোকেন সবাই ডিহাবের ভিতরে থাকে। বাউন্টি ডিহাব টোকেন বা ইউএসডিসি দিয়ে পে করা হয়।',
    workDesc2: 'বাউন্টি হান্টিং চোখে পড়লে সিস্টেমের পুরো গ্রোথ ইঞ্জিনে পরিণত হয়। ক্রিয়েটররা শেয়ার, ক্লিপ, রিকেশন বা তাদের কাজ ছড়িয়ে পড়ার জন্য বাউন্টি পোস্ট করে এনগেজমেন্ট বাড়াতে এবং তাদের কমিউনিটি গড়ে তোলার জন্য ব্যবহার করে। প্রোজেক্টস এবং ডিহাব কমিউনিটির বড় অংশ বাউন্টি হান্টিং ব্যবহার করে নিজেদের প্রমোশন করতে এবং ইকোসিস্টেম বাড়াতে, নতুন লোকদের আকর্ষণকারী টাস্কের জন্য হান্টারদের পুরস্কার দেয়। একই সিস্টেম যা একটি কন্ট্রাক্ট সেটল করে, একইভাবে একটি কমিউনিটি এনগেজমেন্ট টাস্কও সেটল করে।',
    workB1Desc: 'কেউই ক্লিয়ার ব্রিফ দিয়ে আর ডিহাব টোকেন বা ইউএসডিসিয়ে রিওয়ার্ড দিয়ে বাউন্টি পোস্ট করতে পারে, সেটা হোক কোনো ডেলিভারি কাজ বা শেয়ার, ক্লিপিং, অথবা কন্টেন্ট প্রোমোট করার মতো ইঙ্গেজমেন্ট টাস্ক।',
