    mikeBio: "Rapz இன் நிறுவனர் மற்றும் CEO, இது முன்னணி UFC மற்றும் குத்துச்சண்டை நட்சத்திரங்களால் ஆதரிக்கப்படும் ஒரு குறிப்பிடத்தக்க உயர்நிலை MMA சண்டை உடை பிராண்ட், BKFC க்கு பிரத்தியேக விநியோக உரிமைகளுடன். First Class இன் நிறுவனர், UK இன் மிகப்பெரிய TikTok பங்குதாரர் ஏஜென்சி, TikTok UK தலைமையகத்தில் உள் ஏஜென்சி திட்டத்தின் ஒரு பகுதியாக TikTok க்காக நேரடியாக பணிபுரிகிறார், கிட்டத்தட்ட 1000 ஸ்ட்ரீமர்கள் கையெழுத்திடப்பட்டு உள் நிர்வாக குழுவிற்கு நேரடியாக அறிக்கை அளிக்கின்றனர், UK மற்றும் ஆசியாவில் அலுவலகங்களுடன்.",
    mikeExp1: "தனது நேரடி ஸ்ட்ரீம்களுடன் UK சார்ட்களில் 10 மாதங்கள் முன்னிலை வகித்த பிறகு TikTok நிர்வாகிகளால் தேர்ந்தெடுக்கப்பட்டார்",
    mikeExp2: "Lean Chad Fight Club மற்றும் Rapz Sport இன் பின்னால் உள்ள டிஜிட்டல் மற்றும் கலப்பு தற்காப்புக் கலைஞர்",
    mikeExp3: "சமீபத்தில் NGNE உடன் இணைந்த UK இன் முன்னணி கோப்ரா பேக் வழங்குநரின் உரிமையாளர்",
    mikeExp4: "Connor Mcgregor க்கு சொந்தமான BKFC க்கு பிரத்தியேக சண்டை கியர் சப்ளையர், மேலும் அதே பயிற்சியாளர் John Kavanagh யின் கீழ் பயிற்சி பெற்றவர்",
    indiName: "Indi Jay Cammish",
    indiRole: "இணை நிறுவனர்",
    indiBio: "சமூக ஊடகங்கள், உள்ளடக்கம் & நடன நிபுணர், தகவல் தொடர்பு மற்றும் பெருநிறுவன உறவுகளை மேற்பார்வையிடுகிறார். First Class இன் இணை நிறுவனர், UK இன் மிகப்பெரிய TikTok பங்குதாரர் ஏஜென்சி, TikTok UK தலைமையகத்தில் உள் ஏஜென்சி திட்டத்தின் ஒரு பகுதியாக TikTok க்காக நேரடியாக பணிபுரிகிறார்.",
    indiExp1: "Mabel போன்ற உலகளாவிய நட்சத்திரங்களுடன் நீண்டகால உலக சுற்றுப்பயணங்களில் நேரடியாக பணிபுரிந்த அனுபவம் மிக்கவர்",
    indiExp2: "2022 ஆம் ஆண்டு கோடையில் ராணி மாட்சிமைப்படுத்தப்பட்டவர்களுக்கு The Palace இல் நடந்த Platinum Party நிகழ்வில் பங்கேற்றார்",
    indiExp3: "First Class இன் இணை நிறுவனர், UK இன் மிகப்பெரிய TikTok பங்குதாரர் ஏஜென்சி, TikTok UK தலைமையகத்தில் உள் ஏஜென்சி திட்டத்தின் ஒரு பகுதியாக TikTok க்காக நேரடியாக பணிபுரிகிறார்",
    baileyName: "Bailey Young",
    baileyRole: "இணை நிறுவனர்",
    baileyBio: "செயல்பாட்டு வல்லமைசாலி மற்றும் முன்னாள் ப்ரோ-கேமர், கேமிங், இசை மற்றும் பொழுதுபோக்கு துறைகளில் பெரும் தொடர்புகள் கொண்டவர்.",
    baileyExp1: "2021 இல் DeHub இன் வானியல் வளர்ச்சிக்கு முக்கிய பங்கு வகித்த முதலீடுகள் மற்றும் டோக்கனோமிக்ஸ் நிபுணர்",
    baileyExp2: "2023 இல் $1,000,000க்கான Blocjerk நிதி திரட்டலை மேற்பார்வையிட்டார், இது 1,000% உச்ச ROI ஐ அளித்தது",
    baileyExp3: "முன்னாள் தொழில்முறை கேமர், RickyBobby என்ற டேக்கின் கீழ் COD MW2 இல் உலகளவில் முதல் 3 இடங்களையும் Warzone இல் முதல் 100 இடங்களையும் பிடித்தார்",
