    title: 'আইনি দাবিত্যাগ',
    lastUpdated: 'সর্বশেষ আপডেট:',
    lastUpdatedDate: 'মঙ্গলবার, সেপ্টেম্বর 22, 2022',
    effective: 'কার্যকর:',
    effectiveDate: 'জুলাই 15, 2021',
    heading: 'আইনি দাবিত্যাগ',
    paragraph1: 'DeHub টিম, কমিউনিটি বা অ্যাফিলিয়েটদের দ্বারা প্রত্যক্ষ বা পরোক্ষভাবে দেওয়া সব তথ্য শুধু সাধারণ তথ্য বা প্রচারের উদ্দেশ্যে। এইডা বিনিয়োগ বা আর্থিক পরামর্শ, সুপারিশ বা কোনো ধরনের সলিসিটেশন না।',
    paragraph2: 'DeHub প্ল্যাটফর্মে DeHub টোকেনের যেকোনো ব্যবহার প্রত্যাখ্যান গরার অধিকার সংরক্ষণ গরে।',
    paragraph3: 'প্রযোজ্য আইনে অনুমোদিত সর্বোচ্চ পরিমাণে: (i) DeHub টোকেন "যেমন আছে" আর "যেমন পাওয়া যায়" ভিত্তিতে দেওয়া অয়; (ii) DeHub গ্যারান্টি দেয় না যে টোকেন নির্ভরযোগ্য, বর্তমান বা ত্রুটিমুক্ত; (iii) DeHub গ্যারান্টি দিতে পারে না যে টোকেন ভাইরাস বা ক্ষতিকর উপাদানমুক্ত।',
    paragraph4: 'এই ওয়েবসাইটে কোনো শর্ত প্রসপেক্টাস, অফার ডকুমেন্ট বা সিকিউরিটিজের অফার গঠন গরে না।',
    paragraph5: 'এই ওয়েবসাইট বা এর কোনো অংশ এমন কোনো দেশে প্রেরণ গরা যাইবো না যেইহানে এই ডকুমেন্টের বিতরণ নিষিদ্ধ বা সীমাবদ্ধ।',
    paragraph6: 'প্রযোজ্য আইনে অনুমোদিত সর্বোচ্চ পরিমাণে DeHub, এর প্রতিষ্ঠাতা, টিম সদস্য আর যেকোনো তৃতীয় পক্ষ কোনো প্রত্যক্ষ, পরোক্ষ বা বিশেষ ক্ষতির লাইগা দায়ী না।',
    paragraph7: 'প্রযোজ্য আইনে অনুমোদিত সর্বোচ্চ পরিমাণে: কোনো ক্ষেত্রেই DeHub কোনো পরোক্ষ, বিশেষ, আনুষঙ্গিক বা দৃষ্টান্তমূলক ক্ষতির লাইগা দায়ী অইবো না।',
    paragraph8: 'এই ওয়েবসাইটের সব বিবৃতি "ফরওয়ার্ড-লুকিং স্টেটমেন্ট" গঠন গরে। কোনো দেওয়া তথ্যরে ব্যবসায়িক, আইনি, আর্থিক বা অন্য পরামর্শ বইলা মনে গরা উচিত না।',
    paragraph9: 'সব DeHub প্রাপকদের নিজের ওয়ালেট সুরক্ষিত গরার লাইগা যুক্তিসঙ্গত ব্যবস্থা নেওয়ার দায়িত্ব আছে। DeHub হারানো অ্যাক্সেস ক্রেডেনশিয়ালের সাথে সম্পর্কিত কোনো ক্ষতির লাইগা দায়ী না।',
    importantNotice: 'গুরুত্বপূর্ণ নোটিশ',
